881	        self.errors | self.warnings
882	    }
883	
884	    /// Whether there were both errors and warnings.
885	    pub fn both(self) -> bool {
886	        self.errors & self.warnings
887	    }
888	
889	    /// Apply the `OR` of both fields separately.
890	    pub fn or(mut self, other: Self) -> Self {
891	        self.errors |= other.errors;
892	        self.warnings |= other.warnings;
