1299	/// Access to leaves.
1300	impl LinkedNode<'_> {
1301	    /// Get the rightmost non-trivia leaf before this node.
1302	    pub fn prev_leaf(&self) -> Option<Self> {
1303	        let mut node = self.clone();
1304	        while let Some(prev) = node.prev_sibling() {
1305	            if let Some(leaf) = prev.rightmost_leaf() {
1306	                return Some(leaf);
1307	            }
1308	            node = prev;
1309	        }
1310	        self.parent()?.prev_leaf()
1311	    }
