1313	    /// Find the leftmost contained non-trivia leaf.
1314	    pub fn leftmost_leaf(&self) -> Option<Self> {
1315	        if self.is_leaf() && !self.kind().is_trivia() && !self.kind().is_error() {
1316	            return Some(self.clone());
1317	        }
1318	
1319	        for child in self.children() {
1320	            if let Some(leaf) = child.leftmost_leaf() {
1321	                return Some(leaf);
1322	            }
1323	        }
1324	
1325	        None
1326	    }
