70	    nesting: &mut usize,
71	    top_level: bool,
72	) -> Option<Vec<SyntaxNode>> {
73	    let mut p = Parser::new(text, range.start, SyntaxMode::Markup);
74	    *at_start |= p.had_newline();
75	    while !p.end() && p.current_start() < range.end {
76	        // If not top-level and at a new RightBracket, stop the reparse.
77	        if !top_level && *nesting == 0 && p.at(SyntaxKind::RightBracket) {
78	            break;
79	        }
80	        markup_expr(&mut p, *at_start, nesting);
81	        *at_start = p.had_newline();
82	    }
83	    (p.balanced && p.current_start() == range.end).then(|| p.finish())
84	}
