86	/// Parses a single markup expression. This includes markup elements like text,
87	/// headings, strong/emph, lists/enums, etc. This is also the entry point for
88	/// parsing math equations and embedded code expressions.
89	fn markup_expr(p: &mut Parser, at_start: bool, nesting: &mut usize) {
90	    let Some(p) = &mut p.increase_depth() else { return };
91	
92	    match p.current() {
93	        SyntaxKind::LeftBracket => {
94	            *nesting += 1;
95	            p.convert_and_eat(SyntaxKind::Text);
96	        }
97	        SyntaxKind::RightBracket if *nesting > 0 => {
98	            *nesting -= 1;
99	            p.convert_and_eat(SyntaxKind::Text);
100	        }
101	        SyntaxKind::RightBracket => {
102	            p.unexpected();
103	            p.hint("try using a backslash escape: \\]");
104	        }
105	
106	        SyntaxKind::Shebang => p.eat(),
107	
108	        SyntaxKind::Text
109	        | SyntaxKind::Linebreak
110	        | SyntaxKind::Escape
111	        | SyntaxKind::Shorthand
112	        | SyntaxKind::SmartQuote
113	        | SyntaxKind::Link
114	        | SyntaxKind::Label => p.eat(),
115	
116	        SyntaxKind::Raw => p.eat(), // Raw is handled entirely in the Lexer.
117	
118	        SyntaxKind::Hash => embedded_code_expr(p),
119	        SyntaxKind::Star => strong(p),
120	        SyntaxKind::Underscore => emph(p),
121	        SyntaxKind::HeadingMarker if at_start => heading(p),
122	        SyntaxKind::ListMarker if at_start => list_item(p),
123	        SyntaxKind::EnumMarker if at_start => enum_item(p),
124	        SyntaxKind::TermMarker if at_start => term_item(p),
125	        SyntaxKind::RefMarker => reference(p),
126	        SyntaxKind::Dollar => equation(p),
127	
128	        SyntaxKind::HeadingMarker
129	        | SyntaxKind::ListMarker
130	        | SyntaxKind::EnumMarker
131	        | SyntaxKind::TermMarker
132	        | SyntaxKind::Colon => p.convert_and_eat(SyntaxKind::Text),
133	
134	        _ => p.unexpected(),
135	    }
136	}
