138	/// Parses strong content: `*Strong*`.
139	fn strong(p: &mut Parser) {
140	    p.with_nl_mode(AtNewline::StopParBreak, |p| {
141	        let m = p.marker();
142	        p.assert(SyntaxKind::Star);
143	        markup(p, false, true, syntax_set!(Star, RightBracket, End));
144	        let had_closing = p.expect_closing_delimiter(m, SyntaxKind::Star);
145	        p.wrap(m, SyntaxKind::Strong);
146	        if had_closing && p[m].len() == 2 {
147	            p[m].warn("no text within stars");
148	            let hint = "using multiple consecutive stars (e.g. **) has no \
149	                        additional effect";
150	            p[m].hint(hint);
151	        }
152	    });
153	}
