161	        let had_closing = p.expect_closing_delimiter(m, SyntaxKind::Underscore);
162	        p.wrap(m, SyntaxKind::Emph);
163	        if had_closing && p[m].len() == 2 {
164	            p[m].warn("no text within underscores");
165	            let hint = "using multiple consecutive underscores (e.g. __) has no \
166	                        additional effect";
167	            p[m].hint(hint);
168	        }
169	    });
170	}
