237	/// Parses the contents of a mathematical equation: `x^2 + 1`.
238	fn math(p: &mut Parser, stop_set: SyntaxSet) {
239	    let m = p.marker();
240	    math_exprs(p, stop_set);
241	    p.wrap(m, SyntaxKind::Math);
242	}
