244	/// Parses a sequence of math expressions. Returns the number of expressions
245	/// parsed (including errors).
246	fn math_exprs(p: &mut Parser, stop_set: SyntaxSet) -> usize {
247	    debug_assert!(stop_set.contains(SyntaxKind::End));
248	    let Some(p) = p.check_depth_until(stop_set) else { return 1 };
249	
250	    let mut count = 0;
251	    while !p.at_set(stop_set) {
252	        if p.at_set(set::MATH_EXPR) {
253	            math_expr(p);
254	        } else {
255	            p.unexpected();
256	        }
257	        count += 1;
258	    }
259	    count
260	}
