268	/// Parses a math expression with at least the given precedence, possibly
269	/// chaining with another operator by returning early.
270	fn math_expr_prec(p: &mut Parser, min_prec: u8, stop_set: SyntaxSet) {
271	    let Some(p) = &mut p.increase_depth() else { return };
272	
273	    let m = p.marker();
274	    // Whether this expression can group with a following open delimiter as an
275	    // implicit function call.
276	    let mut continuable = false;
277	    match p.current() {
278	        SyntaxKind::Hash => embedded_code_expr(p),
279	
280	        // The lexer manages creating full MathFieldAccess nodes if needed.
281	        SyntaxKind::MathIdent | SyntaxKind::MathFieldAccess => {
282	            continuable = true;
283	            p.eat();
284	            // Parse a function call for an identifier or field access.
285	            if MATH_FUNC_PREC >= min_prec && p.directly_at(SyntaxKind::LeftParen) {
286	                math_args(p);
287	                p.wrap(m, SyntaxKind::MathCall);
288	                continuable = false;
289	            }
290	        }
291	
292	        // Parse delimiters as an atomic unit.
293	        SyntaxKind::MathOpening | SyntaxKind::LeftParen => {
294	            math_delimited(p);
295	        }
296	        // An unmatched closing delimiter.
297	        SyntaxKind::MathClosing | SyntaxKind::RightParen => {
298	            p.convert_and_eat(SyntaxKind::MathClosing);
299	        }
300	
301	        SyntaxKind::Bang | SyntaxKind::Comma | SyntaxKind::Semicolon => {
302	            p.convert_and_eat(SyntaxKind::MathSymbol);
303	        }
304	
305	        SyntaxKind::Linebreak
306	        | SyntaxKind::MathAlignPoint
307	        | SyntaxKind::MathSymbol
308	        | SyntaxKind::MathNumber
309	        | SyntaxKind::MathShorthand => p.eat(),
310	
311	        SyntaxKind::MathLetter
312	        | SyntaxKind::MathPrimes
313	        | SyntaxKind::Escape
314	        | SyntaxKind::Str => {
315	            continuable = true;
316	            p.eat();
317	        }
318	
319	        // The only prefix operator in math.
320	        SyntaxKind::Root => {
321	            p.eat();
322	            let m2 = p.marker();
323	            math_expr_prec(p, MATH_ROOT_PREC, syntax_set!());
324	            math_unparen(p, m2);
325	            p.wrap(m, SyntaxKind::MathRoot);
326	        }
327	
328	        _ => p.expected("expression"),
329	    }
330	
331	    // Maybe recognize an implicit function call: a 'continuable' token followed
332	    // by delimiters will group as one with the precedence of a normal function.
333	    // E.g. `a(b)/c` parses as `(a(b))/c` when `a` is continuable.
334	    if continuable
335	        && MATH_FUNC_PREC >= min_prec
336	        && !p.had_trivia()
337	        && p.at_set(syntax_set!(MathOpening, LeftParen))
338	    {
339	        math_delimited(p);
340	        p.wrap(m, SyntaxKind::Math);
341	    }
342	
343	    // Parse infix and postfix operators. The general form of a parsed op looks
344	    // like: `MathAttach[ MathLetter("x"), Hat("^"), MathNumber("2") ]`.
345	    while !p.at_set(stop_set)
346	        && let op_kind = p.current()
347	        && let had_trivia = p.had_trivia()
348	        && let Some((wrapper, infix_assoc, prec)) = math_op(op_kind, had_trivia)
349	        && prec >= min_prec
350	    {
351	        // Prepare a chaining set for the attachment operators.
352	        let mut chain_set = if wrapper == SyntaxKind::MathAttach {
353	            // Hat can chain with Underscore, Underscore can chain with Hat, and
354	            // Prime can chain with either (but prime can't interrupt a chain,
355	            // see below).
356	            syntax_set!(Hat, Underscore).remove(op_kind)
357	        } else {
358	            syntax_set!()
359	        };
360	
361	        // Eat the operator itself.
362	        if op_kind == SyntaxKind::Bang {
363	            p.convert_and_eat(SyntaxKind::MathSymbol);
364	        } else {
365	            p.eat();
366	        }
367	
368	        // Slash is the only operator that removes parens from its left operand.
369	        if wrapper == SyntaxKind::MathFrac {
370	            math_unparen(p, m);
371	        }
372	
373	        // Parse the operator's right operand.
374	        if let Some(assoc) = infix_assoc {
375	            let prec = match assoc {
376	                ast::Assoc::Left => prec + 1,
377	                ast::Assoc::Right => prec,
378	            };
379	            let m_rhs = p.marker();
380	            math_expr_prec(p, prec, chain_set);
381	            math_unparen(p, m_rhs);
382	        }
383	
384	        // Avoid interrupting a chain when initially parsing a prime.
385	        // For `a^b'_c^d` the grouping is `(a^(b')_c)^d` and not `a^(b'_c^d)`.
386	        if !(op_kind == SyntaxKind::MathPrimes && p.at_set(stop_set)) {
387	            // Parse chained attachment operators as a single attachment.
388	            while p.at_set(chain_set) {
389	                chain_set = chain_set.remove(p.current());
390	                p.eat();
391	                let m_chain_rhs = p.marker();
392	                math_expr_prec(p, prec, chain_set);
393	                math_unparen(p, m_chain_rhs);
394	            }
395	        }
396	
397	        // Finish the operator by wrapping from its left operand.
398	        p.wrap(m, wrapper);
399	    }
400	}
