402	// These are declared here so they're easier to compare with `math_op`.
403	const MATH_FUNC_PREC: u8 = 2;
404	const MATH_ROOT_PREC: u8 = 2;
405	
406	/// Precedence and wrapper kinds for infix and postfix math operators.
407	fn math_op(
408	    kind: SyntaxKind,
409	    had_trivia: bool,
410	) -> Option<(SyntaxKind, Option<ast::Assoc>, u8)> {
411	    let op = match kind {
412	        SyntaxKind::Slash => (SyntaxKind::MathFrac, Some(ast::Assoc::Left), 1),
413	        SyntaxKind::Underscore => (SyntaxKind::MathAttach, Some(ast::Assoc::Right), 2),
414	        SyntaxKind::Hat => (SyntaxKind::MathAttach, Some(ast::Assoc::Right), 2),
415	        SyntaxKind::MathPrimes if !had_trivia => (SyntaxKind::MathAttach, None, 2),
416	        SyntaxKind::Bang if !had_trivia => (SyntaxKind::Math, None, 3),
417	        _ => return None,
418	    };
419	    Some(op)
420	}
421	
422	/// Parse matched delimiters in math: `[x + y]`.
423	///
424	/// `{Left,Right}Paren` need to be converted to `Math{Opening,Closing}` since we
425	/// parens are separated out to aid function call parsing. Note that they may be
426	/// converted _back_ to `{Left,Right}Paren` by a later `math_unparen` call.
427	fn math_delimited(p: &mut Parser) {
428	    let m = p.marker();
429	    p.convert_and_eat(SyntaxKind::MathOpening); // Converts `LeftParen`.
430	    let m_body = p.marker();
431	    math_exprs(p, syntax_set!(Dollar, End, MathClosing, RightParen));
432	    if p.at_set(syntax_set!(MathClosing, RightParen)) {
433	        p.wrap(m_body, SyntaxKind::Math);
434	        p.convert_and_eat(SyntaxKind::MathClosing); // Converts `RightParen`.
435	        p.wrap(m, SyntaxKind::MathDelimited);
436	    } else {
437	        // If we had no closing delimiter, just produce a math sequence.
438	        p.wrap(m, SyntaxKind::Math);
439	    }
440	}
441	
442	/// Remove one set of parentheses (if any) from a previously parsed expression
443	/// by converting to non-expression [`SyntaxKind`]s.
444	fn math_unparen(p: &mut Parser, m: Marker) {
445	    let node = &mut p[m];
446	    if node.kind() == SyntaxKind::MathDelimited
447	        && let [first, .., last] = node.children_mut()
448	        && first.leaf_text() == "("
449	        && last.leaf_text() == ")"
450	    {
451	        // `LeftParen` and `RightParen` kinds are skipped in the AST.
452	        first.convert_to_kind(SyntaxKind::LeftParen);
453	        last.convert_to_kind(SyntaxKind::RightParen);
454	        node.convert_to_kind(SyntaxKind::Math);
455	    }
456	}
457	
458	/// Parse an argument list in math: `(a, b; c, d; size: #50%)`.
459	fn math_args(p: &mut Parser) {
460	    let m = p.marker();
461	    p.assert(SyntaxKind::LeftParen);
462	
463	    let mut seen = FxHashSet::default();
464	    while !p.at_set(syntax_set!(End, Dollar, RightParen)) {
465	        math_arg(p, &mut seen);
466	        match p.current() {
467	            SyntaxKind::End | SyntaxKind::Dollar | SyntaxKind::RightParen => {}
468	            SyntaxKind::Semicolon | SyntaxKind::Comma => p.eat(),
469	            _ => p.expected("comma or semicolon"),
470	        }
471	    }
472	
473	    p.expect_closing_delimiter(m, SyntaxKind::RightParen);
474	    p.wrap(m, SyntaxKind::MathArgs);
475	}
476	
477	/// Parses a single argument in a math argument list.
478	fn math_arg<'s>(p: &mut Parser<'s>, seen: &mut FxHashSet<&'s str>) {
479	    let m = p.marker();
480	    let start = p.current_start();
481	
482	    let mut arg_kind = None;
483	
484	    if let Some(spread) = p.lexer.maybe_math_spread_arg(start) {
485	        // Parses a spread argument: `..args`.
486	        arg_kind = Some(SyntaxKind::Spread);
487	        p.token.node = spread;
488	        p.eat();
489	    } else if let Some(named) = p.lexer.maybe_math_named_arg(start) {
490	        // Parses a named argument: `thickness: #12pt`.
491	        arg_kind = Some(SyntaxKind::Named);
492	        p.token.node = named;
493	        let text = p.current_text();
494	        p.eat();
495	        p.convert_and_eat(SyntaxKind::Colon);
496	        if !seen.insert(text) {
497	            p[m].convert_to_error(eco_format!("duplicate argument: {text}"));
498	        }
499	    }
500	
501	    // Parses the argument itself.
502	    let m_arg = p.marker();
503	    let count = math_exprs(p, syntax_set!(End, Dollar, Comma, Semicolon, RightParen));
504	
505	    if count == 0 {
506	        // This can't happen due to checks in `Lexer::maybe_math_spread_arg`.
507	        assert_ne!(arg_kind, Some(SyntaxKind::Spread));
508	
509	        // Named arguments require a value.
510	        if arg_kind == Some(SyntaxKind::Named) {
511	            p.expected("expression");
512	        }
513	    }
514	
515	    // Wrap math function arguments to join adjacent math content or create an
516	    // empty 'Math' node for when we have 0 args. We don't wrap when
517	    // `count == 1`, since wrapping would change the type of the expression
518	    // from potentially non-content to content. E.g. `$ func(#12pt) $` would
519	    // change the type of `#12pt` from size to content if wrapped.
520	    if count != 1 {
521	        p.wrap(m_arg, SyntaxKind::Math);
522	    }
523	
524	    if let Some(kind) = arg_kind {
525	        p.wrap(m, kind);
526	    }
527	}
