529	/// Parses the contents of a code block.
530	fn code(p: &mut Parser, stop_set: SyntaxSet) {
531	    let m = p.marker();
532	    code_exprs(p, stop_set);
533	    p.wrap(m, SyntaxKind::Code);
534	}
535	
536	/// Parses a sequence of code expressions.
537	fn code_exprs(p: &mut Parser, stop_set: SyntaxSet) {
538	    debug_assert!(stop_set.contains(SyntaxKind::End));
539	    let Some(p) = p.check_depth_until(stop_set) else { return };
540	
541	    while !p.at_set(stop_set) {
542	        p.with_nl_mode(AtNewline::ContextualContinue, |p| {
543	            if !p.at_set(set::CODE_EXPR) {
544	                p.unexpected();
545	                return;
546	            }
547	            code_expr(p);
548	            if !p.at_set(stop_set) && !p.eat_if(SyntaxKind::Semicolon) {
549	                p.expected("semicolon or line break");
550	                if p.at(SyntaxKind::Label) {
551	                    p.hint("labels can only be applied in markup mode");
552	                    p.hint("try wrapping your code in a markup block (`[ ]`)");
553	                }
554	            }
555	        });
556	    }
557	}
558	
559	/// Parses an atomic code expression embedded in markup or math.
560	fn embedded_code_expr(p: &mut Parser) {
561	    p.enter_modes(SyntaxMode::Code, AtNewline::Stop, |p| {
562	        p.assert(SyntaxKind::Hash);
563	        if p.had_trivia() || p.end() {
564	            p.expected("expression");
565	            return;
566	        }
567	
568	        let stmt = p.at_set(set::STMT);
569	        code_expr_prec(p, true, 0);
570	
571	        // Note: 2d math arguments rely on the `directly_at` check.
572	        let semi = (stmt || p.directly_at(SyntaxKind::Semicolon))
573	            && p.eat_if(SyntaxKind::Semicolon);
574	
575	        if stmt && !semi && !p.end() && !p.at(SyntaxKind::RightBracket) {
576	            p.expected("semicolon or line break");
577	        }
578	    });
579	}
580	
581	/// Parses a single code expression.
582	fn code_expr(p: &mut Parser) {
583	    code_expr_prec(p, false, 0);
584	}
585	
586	/// Parses a code expression with at least the given precedence.
587	fn code_expr_prec(p: &mut Parser, atomic: bool, min_prec: u8) {
588	    let Some(p) = &mut p.increase_depth() else { return };
589	
590	    let m = p.marker();
591	    if p.at_set(set::UNARY_OP) {
592	        if !atomic {
593	            let op = ast::UnOp::from_kind(p.current()).unwrap();
594	            p.eat();
595	            code_expr_prec(p, atomic, op.precedence());
596	            p.wrap(m, SyntaxKind::Unary);
597	        } else {
598	            p.unexpected();
599	            p.hint(
600	                "to use a unary operator here, wrap the entire expression in parentheses",
601	            );
602	        }
603	    } else {
604	        code_primary(p, atomic);
605	    }
606	
607	    loop {
608	        if p.directly_at(SyntaxKind::LeftParen) || p.directly_at(SyntaxKind::LeftBracket)
609	        {
610	            args(p);
611	            p.wrap(m, SyntaxKind::FuncCall);
612	            continue;
613	        }
614	
615	        let at_field_or_method = p.directly_at(SyntaxKind::Dot)
616	            && p.lexer.clone().next().0 == SyntaxKind::Ident;
617	
618	        if atomic && !at_field_or_method {
619	            break;
620	        }
621	
622	        if p.eat_if(SyntaxKind::Dot) {
623	            p.expect(SyntaxKind::Ident);
624	            p.wrap(m, SyntaxKind::FieldAccess);
625	            continue;
626	        }
627	
628	        let binop = if p.at_set(set::BINARY_OP) {
629	            ast::BinOp::from_kind(p.current())
630	        } else if min_prec <= ast::BinOp::NotIn.precedence() && p.eat_if(SyntaxKind::Not)
631	        {
632	            if p.at(SyntaxKind::In) {
633	                Some(ast::BinOp::NotIn)
634	            } else {
635	                p.expected("keyword `in`");
636	                break;
637	            }
638	        } else {
639	            None
640	        };
641	
642	        if let Some(op) = binop {
643	            let mut prec = op.precedence();
644	            if prec < min_prec {
645	                break;
646	            }
647	
648	            match op.assoc() {
649	                ast::Assoc::Left => prec += 1,
650	                ast::Assoc::Right => {}
651	            }
652	
653	            p.eat();
654	            code_expr_prec(p, false, prec);
655	            p.wrap(m, SyntaxKind::Binary);
656	            continue;
657	        }
658	
659	        break;
660	    }
661	}
