663	/// Parses a primary in a code expression. These are the atoms that unary and
664	/// binary operations, functions calls, and field accesses start with / are
665	/// composed of.
666	fn code_primary(p: &mut Parser, atomic: bool) {
667	    let m = p.marker();
668	    match p.current() {
669	        SyntaxKind::Ident => {
670	            p.eat();
671	            if !atomic && p.at(SyntaxKind::Arrow) {
672	                p.wrap(m, SyntaxKind::Params);
673	                p.assert(SyntaxKind::Arrow);
674	                code_expr(p);
675	                p.wrap(m, SyntaxKind::Closure);
676	            }
677	        }
678	        SyntaxKind::Underscore if !atomic => {
679	            p.eat();
680	            if p.at(SyntaxKind::Arrow) {
681	                p.wrap(m, SyntaxKind::Params);
682	                p.eat();
683	                code_expr(p);
684	                p.wrap(m, SyntaxKind::Closure);
685	            } else if p.eat_if(SyntaxKind::Eq) {
686	                code_expr(p);
687	                p.wrap(m, SyntaxKind::DestructAssignment);
688	            } else {
689	                p[m].expected("expression");
690	            }
691	        }
692	
693	        SyntaxKind::LeftBrace => code_block(p),
694	        SyntaxKind::LeftBracket => content_block(p),
695	        SyntaxKind::LeftParen => expr_with_paren(p, atomic),
696	        SyntaxKind::Dollar => equation(p),
697	        SyntaxKind::Let => let_binding(p),
698	        SyntaxKind::Set => set_rule(p),
699	        SyntaxKind::Show => show_rule(p),
700	        SyntaxKind::Context => contextual(p, atomic),
701	        SyntaxKind::If => conditional(p),
702	        SyntaxKind::While => while_loop(p),
703	        SyntaxKind::For => for_loop(p),
704	        SyntaxKind::Import => module_import(p),
705	        SyntaxKind::Include => module_include(p),
706	        SyntaxKind::Break => break_stmt(p),
707	        SyntaxKind::Continue => continue_stmt(p),
708	        SyntaxKind::Return => return_stmt(p),
709	
710	        SyntaxKind::Raw => p.eat(), // Raw is handled entirely in the Lexer.
711	
712	        SyntaxKind::None
713	        | SyntaxKind::Auto
714	        | SyntaxKind::Int
715	        | SyntaxKind::Float
716	        | SyntaxKind::Bool
717	        | SyntaxKind::Numeric
718	        | SyntaxKind::Str
719	        | SyntaxKind::Label => p.eat(),
720	
721	        // Consume erroneous tokens for things like `#12p`, `#]`, or `#"abc\"`.
722	        _ if atomic => p.unexpected(),
723	
724	        _ => p.expected("expression"),
725	    }
726	}
