728	/// Reparses a full content or code block. This only succeeds if the new block
729	/// contains balanced delimiters.
730	pub(super) fn reparse_block(text: &str, range: Range<usize>) -> Option<SyntaxNode> {
731	    let mut p = Parser::new(text, range.start, SyntaxMode::Code);
732	    assert!(p.at(SyntaxKind::LeftBracket) || p.at(SyntaxKind::LeftBrace));
733	    block(&mut p);
734	    (p.balanced && p.prev_end() == range.end)
735	        .then(|| p.finish().into_iter().next().unwrap())
736	}
