769	/// Parses a let binding: `let x = 1`.
770	fn let_binding(p: &mut Parser) {
771	    let m = p.marker();
772	    p.assert(SyntaxKind::Let);
773	
774	    let m2 = p.marker();
775	    let mut closure = false;
776	    let mut other = false;
777	
778	    if p.eat_if(SyntaxKind::Ident) {
779	        if p.directly_at(SyntaxKind::LeftParen) {
780	            params(p);
781	            closure = true;
782	        }
783	    } else {
784	        pattern(p, false, &mut FxHashSet::default(), None);
785	        other = true;
786	    }
787	
788	    let f = if closure || other { Parser::expect } else { Parser::eat_if };
789	    if f(p, SyntaxKind::Eq) {
790	        code_expr(p);
791	    }
792	
793	    if closure {
794	        p.wrap(m2, SyntaxKind::Closure);
795	    }
796	
797	    p.wrap(m, SyntaxKind::LetBinding);
798	}
