908	            p.with_nl_mode(AtNewline::Continue, |p| {
909	                let m2 = p.marker();
910	                p.assert(SyntaxKind::LeftParen);
911	
912	                import_items(p);
913	
914	                p.expect_closing_delimiter(m2, SyntaxKind::RightParen);
915	            });
