924	/// Parses items to import from a module: `a, b, c`.
925	fn import_items(p: &mut Parser) {
926	    let m = p.marker();
927	    while !p.current().is_terminator() {
928	        let item_marker = p.marker();
929	        if !p.eat_if(SyntaxKind::Ident) {
930	            p.unexpected();
931	        }
932	
933	        // Nested import path: `a.b.c`
934	        while p.eat_if(SyntaxKind::Dot) {
935	            p.expect(SyntaxKind::Ident);
936	        }
937	
938	        p.wrap(item_marker, SyntaxKind::ImportItemPath);
939	
940	        // Rename imported item.
941	        if p.eat_if(SyntaxKind::As) {
942	            p.expect(SyntaxKind::Ident);
943	            p.wrap(item_marker, SyntaxKind::RenamedImportItem);
944	        }
945	
946	        if !p.current().is_terminator() {
947	            p.expect(SyntaxKind::Comma);
948	        }
949	    }
950	
951	    p.wrap(m, SyntaxKind::ImportItems);
952	}
