986	/// An expression that starts with a parenthesis.
987	fn expr_with_paren(p: &mut Parser, atomic: bool) {
988	    if atomic {
989	        // Atomic expressions aren't modified by operators that follow them, so
990	        // our first guess of array/dict will be correct.
991	        parenthesized_or_array_or_dict(p);
992	        return;
993	    }
994	
995	    // If we've seen this position before and have a memoized result, restore it
996	    // and return. Otherwise, get a key to this position and a checkpoint to
997	    // restart from in case we make a wrong prediction.
998	    let Some((memo_key, checkpoint)) = p.restore_memo_or_checkpoint() else { return };
999	    // The node length from when we restored.
1000	    let prev_len = checkpoint.node_len;
1001	
1002	    // When we reach a '(', we can't be sure what it is. First, we attempt to
1003	    // parse as a simple parenthesized expression, array, or dictionary as
1004	    // these are the most likely things. We can handle all of those in a single
1005	    // pass.
1006	    let kind = parenthesized_or_array_or_dict(p);
1007	
1008	    // If, however, '=>' or '=' follows, we must backtrack and reparse as either
1009	    // a parameter list or a destructuring. To be able to do that, we created a
1010	    // parser checkpoint before our speculative parse, which we can restore.
1011	    //
1012	    // However, naive backtracking has a fatal flaw: It can lead to exponential
1013	    // parsing time if we are constantly getting things wrong in a nested
1014	    // scenario. The particular failure case for parameter parsing is the
1015	    // following: `(x: (x: (x) => y) => y) => y`
1016	    //
1017	    // Such a structure will reparse over and over again recursively, leading to
1018	    // a running time of O(2^n) for nesting depth n. To prevent this, we perform
1019	    // a simple trick: When we have done the mistake of picking the wrong path
1020	    // once and have subsequently parsed correctly, we save the result of that
1021	    // correct parsing in the `p.memo` map. When we reach the same position
1022	    // again, we can then just restore this result. In this way, no
1023	    // parenthesized expression is parsed more than twice, leading to a worst
1024	    // case running time of O(2n).
1025	    if p.at(SyntaxKind::Arrow) {
1026	        p.restore(checkpoint);
1027	        let m = p.marker();
1028	        params(p);
1029	        if !p.expect(SyntaxKind::Arrow) {
1030	            return;
1031	        }
1032	        code_expr(p);
1033	        p.wrap(m, SyntaxKind::Closure);
1034	    } else if p.at(SyntaxKind::Eq) && kind != SyntaxKind::Parenthesized {
1035	        p.restore(checkpoint);
1036	        let m = p.marker();
1037	        destructuring_or_parenthesized(p, true, &mut FxHashSet::default());
1038	        if !p.expect(SyntaxKind::Eq) {
1039	            return;
1040	        }
1041	        code_expr(p);
1042	        p.wrap(m, SyntaxKind::DestructAssignment);
1043	    } else {
1044	        return;
1045	    }
1046	
1047	    // Memoize result if we backtracked.
1048	    p.memoize_parsed_nodes(memo_key, prev_len);
1049	}
1050	
1051	/// Parses either
1052	/// - a parenthesized expression: `(1 + 2)`, or
1053	/// - an array: `(1, "hi", 12cm)`, or
1054	/// - a dictionary: `(thickness: 3pt, dash: "solid")`.
1055	fn parenthesized_or_array_or_dict(p: &mut Parser) -> SyntaxKind {
1056	    let mut state = GroupState {
1057	        count: 0,
1058	        maybe_just_parens: true,
1059	        kind: None,
1060	        seen: FxHashSet::default(),
1061	    };
1062	
1063	    // An edge case with parens is whether we can interpret a leading spread
1064	    // expression as a dictionary, e.g. if we want `(..dict1, ..dict2)` to join
1065	    // the two dicts.
1066	    //
1067	    // The issue is that we decide on the type of the parenthesized expression
1068	    // here in the parser by the `SyntaxKind` we wrap with, instead of in eval
1069	    // based on the type of the spread item.
1070	    //
1071	    // The current fix is that we allow a leading colon to force the
1072	    // parenthesized value into a dict:
1073	    // - `(..arr1, ..arr2)` is wrapped as an `Array`.
1074	    // - `(: ..dict1, ..dict2)` is wrapped as a `Dict`.
1075	    //
1076	    // This does allow some unexpected expressions, such as `(: key: val)`, but
1077	    // it's currently intentional.
1078	    let m = p.marker();
1079	    p.with_nl_mode(AtNewline::Continue, |p| {
1080	        p.assert(SyntaxKind::LeftParen);
1081	        if p.eat_if(SyntaxKind::Colon) {
1082	            state.kind = Some(SyntaxKind::Dict);
1083	        }
1084	
1085	        while !p.current().is_terminator() {
1086	            if !p.at_set(set::ARRAY_OR_DICT_ITEM) {
1087	                p.unexpected();
1088	                continue;
1089	            }
1090	
1091	            array_or_dict_item(p, &mut state);
1092	            state.count += 1;
1093	
1094	            if !p.current().is_terminator() && p.expect(SyntaxKind::Comma) {
1095	                state.maybe_just_parens = false;
1096	            }
1097	        }
1098	
1099	        p.expect_closing_delimiter(m, SyntaxKind::RightParen);
1100	    });
1101	
1102	    let kind = if state.maybe_just_parens && state.count == 1 {
1103	        SyntaxKind::Parenthesized
1104	    } else {
1105	        state.kind.unwrap_or(SyntaxKind::Array)
1106	    };
1107	
1108	    p.wrap(m, kind);
1109	    kind
1110	}
1111	
1112	/// State for array/dictionary parsing.
1113	struct GroupState {
1114	    count: usize,
1115	    /// Whether this is just a single expression in parens: `(a)`. Single
1116	    /// element arrays require an explicit comma: `(a,)`, unless we're
1117	    /// spreading: `(..a)`.
1118	    maybe_just_parens: bool,
1119	    /// The `SyntaxKind` to wrap as (if we've figured it out yet).
1120	    kind: Option<SyntaxKind>,
1121	    /// Store named arguments so we can give an error if they're repeated.
1122	    seen: FxHashSet<EcoString>,
1123	}
1124	
1125	/// Parses a single item in an array or dictionary.
1126	fn array_or_dict_item(p: &mut Parser, state: &mut GroupState) {
1127	    let m = p.marker();
1128	
1129	    if p.eat_if(SyntaxKind::Dots) {
1130	        // Parses a spread item: `..item`.
1131	        code_expr(p);
1132	        p.wrap(m, SyntaxKind::Spread);
1133	        state.maybe_just_parens = false;
1134	        return;
1135	    }
1136	
1137	    code_expr(p);
1138	
1139	    if p.eat_if(SyntaxKind::Colon) {
1140	        // Parses a named/keyed pair: `name: item` or `"key": item`.
1141	        code_expr(p);
1142	
1143	        let node = &mut p[m];
1144	        let pair_kind = match node.kind() {
1145	            SyntaxKind::Ident => SyntaxKind::Named,
1146	            _ => SyntaxKind::Keyed,
1147	        };
1148	
1149	        if let Some(key) = match node.cast::<ast::Expr>() {
1150	            Some(ast::Expr::Ident(ident)) => Some(ident.get().clone()),
1151	            Some(ast::Expr::Str(s)) => Some(s.get()),
1152	            _ => None,
1153	        } && !state.seen.insert(key.clone())
1154	        {
1155	            node.convert_to_error(eco_format!("duplicate key: {key}"));
1156	        }
1157	
1158	        p.wrap(m, pair_kind);
1159	        state.maybe_just_parens = false;
1160	
1161	        if state.kind == Some(SyntaxKind::Array) {
1162	            p[m].expected("expression");
1163	        } else {
1164	            state.kind = Some(SyntaxKind::Dict);
1165	        }
1166	    } else {
1167	        // Parses a positional item.
1168	        if state.kind == Some(SyntaxKind::Dict) {
1169	            p[m].expected("named or keyed pair");
1170	        } else {
1171	            state.kind = Some(SyntaxKind::Array);
1172	        }
1173	    }
1174	}
