1176	/// Parses a function call's argument list: `(12pt, y)`.
1177	fn args(p: &mut Parser) {
1178	    if !p.directly_at(SyntaxKind::LeftParen) && !p.directly_at(SyntaxKind::LeftBracket) {
1179	        p.expected("argument list");
1180	        if p.at(SyntaxKind::LeftParen) || p.at(SyntaxKind::LeftBracket) {
1181	            p.hint("there may not be any spaces before the argument list");
1182	        }
1183	    }
1184	
1185	    let m = p.marker();
1186	    if p.at(SyntaxKind::LeftParen) {
1187	        let m2 = p.marker();
1188	        p.with_nl_mode(AtNewline::Continue, |p| {
1189	            p.assert(SyntaxKind::LeftParen);
1190	
1191	            let mut seen = FxHashSet::default();
1192	            while !p.current().is_terminator() {
1193	                if !p.at_set(set::ARG) {
1194	                    p.unexpected();
1195	                    continue;
1196	                }
1197	
1198	                arg(p, &mut seen);
1199	
1200	                if !p.current().is_terminator() {
1201	                    p.expect(SyntaxKind::Comma);
1202	                }
1203	            }
1204	
1205	            p.expect_closing_delimiter(m2, SyntaxKind::RightParen);
1206	        });
1207	    }
1208	
1209	    while p.directly_at(SyntaxKind::LeftBracket) {
1210	        content_block(p);
1211	    }
1212	
1213	    p.wrap(m, SyntaxKind::Args);
1214	}
