1216	/// Parses a single argument in an argument list.
1217	fn arg<'s>(p: &mut Parser<'s>, seen: &mut FxHashSet<&'s str>) {
1218	    let m = p.marker();
1219	
1220	    // Parses a spread argument: `..args`.
1221	    if p.eat_if(SyntaxKind::Dots) {
1222	        code_expr(p);
1223	        p.wrap(m, SyntaxKind::Spread);
1224	        return;
1225	    }
1226	
1227	    // Parses a normal positional argument or an argument name.
1228	    let was_at_expr = p.at_set(set::CODE_EXPR);
1229	    let text = p.current_text();
1230	    code_expr(p);
1231	
1232	    // Parses a named argument: `thickness: 12pt`.
1233	    if p.eat_if(SyntaxKind::Colon) {
1234	        // Recover from bad argument name.
1235	        if was_at_expr {
1236	            if p[m].kind() != SyntaxKind::Ident {
1237	                p[m].expected("identifier");
1238	            } else if !seen.insert(text) {
1239	                p[m].convert_to_error(eco_format!("duplicate argument: {text}"));
1240	            }
1241	        }
1242	
1243	        code_expr(p);
1244	        p.wrap(m, SyntaxKind::Named);
1245	    }
1246	}
