1248	/// Parses a closure's parameters: `(x, y)`.
1249	fn params(p: &mut Parser) {
1250	    let m = p.marker();
1251	    p.with_nl_mode(AtNewline::Continue, |p| {
1252	        p.assert(SyntaxKind::LeftParen);
1253	
1254	        let mut seen = FxHashSet::default();
1255	        let mut sink = false;
1256	
1257	        while !p.current().is_terminator() {
1258	            if !p.at_set(set::PARAM) {
1259	                p.unexpected();
1260	                continue;
1261	            }
1262	
1263	            param(p, &mut seen, &mut sink);
1264	
1265	            if !p.current().is_terminator() {
1266	                p.expect(SyntaxKind::Comma);
1267	            }
1268	        }
1269	
1270	        p.expect_closing_delimiter(m, SyntaxKind::RightParen);
1271	    });
1272	    p.wrap(m, SyntaxKind::Params);
1273	}
1274	
1275	/// Parses a single parameter in a parameter list.
1276	fn param<'s>(p: &mut Parser<'s>, seen: &mut FxHashSet<&'s str>, sink: &mut bool) {
1277	    let m = p.marker();
1278	
1279	    // Parses argument sink: `..sink`.
1280	    if p.eat_if(SyntaxKind::Dots) {
1281	        if p.at_set(set::PATTERN_LEAF) {
1282	            pattern_leaf(p, false, seen, Some("parameter"));
1283	        }
1284	        p.wrap(m, SyntaxKind::Spread);
1285	        if mem::replace(sink, true) {
1286	            p[m].convert_to_error("only one argument sink is allowed");
1287	        }
1288	        return;
1289	    }
1290	
1291	    // Parses a normal positional parameter or a parameter name.
1292	    let was_at_pat = p.at_set(set::PATTERN);
1293	    pattern(p, false, seen, Some("parameter"));
1294	
1295	    // Parses a named parameter: `thickness: 12pt`.
1296	    if p.eat_if(SyntaxKind::Colon) {
1297	        // Recover from bad parameter name.
1298	        if was_at_pat && p[m].kind() != SyntaxKind::Ident {
1299	            p[m].expected("identifier");
1300	        }
1301	
1302	        code_expr(p);
1303	        p.wrap(m, SyntaxKind::Named);
1304	    }
1305	}
1306	
1307	/// Parses a binding or reassignment pattern.
1308	fn pattern<'s>(
1309	    p: &mut Parser<'s>,
1310	    reassignment: bool,
1311	    seen: &mut FxHashSet<&'s str>,
1312	    dupe: Option<&'s str>,
1313	) {
1314	    let Some(p) = &mut p.increase_depth() else { return };
1315	
1316	    match p.current() {
1317	        SyntaxKind::Underscore => p.eat(),
1318	        SyntaxKind::LeftParen => destructuring_or_parenthesized(p, reassignment, seen),
1319	        _ => pattern_leaf(p, reassignment, seen, dupe),
1320	    }
1321	}
1322	
1323	/// Parses a destructuring pattern or just a parenthesized pattern.
1324	fn destructuring_or_parenthesized<'s>(
1325	    p: &mut Parser<'s>,
1326	    reassignment: bool,
1327	    seen: &mut FxHashSet<&'s str>,
1328	) {
1329	    let mut sink = false;
1330	    let mut count = 0;
1331	    let mut maybe_just_parens = true;
1332	
1333	    let m = p.marker();
1334	    p.with_nl_mode(AtNewline::Continue, |p| {
1335	        p.assert(SyntaxKind::LeftParen);
1336	
1337	        while !p.current().is_terminator() {
1338	            if !p.at_set(set::DESTRUCTURING_ITEM) {
1339	                p.unexpected();
1340	                continue;
1341	            }
1342	
1343	            destructuring_item(p, reassignment, seen, &mut maybe_just_parens, &mut sink);
1344	            count += 1;
1345	
1346	            if !p.current().is_terminator() && p.expect(SyntaxKind::Comma) {
1347	                maybe_just_parens = false;
1348	            }
1349	        }
1350	
1351	        p.expect_closing_delimiter(m, SyntaxKind::RightParen);
1352	    });
1353	
1354	    if maybe_just_parens && count == 1 && !sink {
1355	        p.wrap(m, SyntaxKind::Parenthesized);
1356	    } else {
1357	        p.wrap(m, SyntaxKind::Destructuring);
1358	    }
1359	}
1360	
1361	/// Parses an item in a destructuring pattern.
1362	fn destructuring_item<'s>(
1363	    p: &mut Parser<'s>,
1364	    reassignment: bool,
1365	    seen: &mut FxHashSet<&'s str>,
1366	    maybe_just_parens: &mut bool,
1367	    sink: &mut bool,
1368	) {
1369	    let m = p.marker();
1370	
1371	    // Parse destructuring sink: `..rest`.
1372	    if p.eat_if(SyntaxKind::Dots) {
1373	        if p.at_set(set::PATTERN_LEAF) {
1374	            pattern_leaf(p, reassignment, seen, None);
1375	        }
1376	        p.wrap(m, SyntaxKind::Spread);
1377	        if mem::replace(sink, true) {
1378	            p[m].convert_to_error("only one destructuring sink is allowed");
1379	        }
1380	        return;
1381	    }
1382	
1383	    // Parse a normal positional pattern or a destructuring key.
1384	    let was_at_pat = p.at_set(set::PATTERN);
1385	
1386	    // We must use a full checkpoint here (can't just clone the lexer) because
1387	    // there may be trivia between the identifier and the colon we need to skip.
1388	    let checkpoint = p.checkpoint();
1389	    if !(p.eat_if(SyntaxKind::Ident) && p.at(SyntaxKind::Colon)) {
1390	        p.restore(checkpoint);
1391	        pattern(p, reassignment, seen, None);
1392	    }
1393	
1394	    // Parse named destructuring item.
1395	    if p.eat_if(SyntaxKind::Colon) {
1396	        // Recover from bad named destructuring.
1397	        if was_at_pat && p[m].kind() != SyntaxKind::Ident {
1398	            p[m].expected("identifier");
1399	        }
1400	
1401	        pattern(p, reassignment, seen, None);
1402	        p.wrap(m, SyntaxKind::Named);
1403	        *maybe_just_parens = false;
1404	    }
1405	}
1406	
1407	/// Parses a leaf in a pattern - either an identifier or an expression
1408	/// depending on whether it's a binding or reassignment pattern.
1409	fn pattern_leaf<'s>(
1410	    p: &mut Parser<'s>,
1411	    reassignment: bool,
1412	    seen: &mut FxHashSet<&'s str>,
1413	    dupe: Option<&'s str>,
1414	) {
1415	    if p.current().is_keyword() {
1416	        p.eat_and_get().expected("pattern");
1417	        return;
1418	    } else if !p.at_set(set::PATTERN_LEAF) {
1419	        p.expected("pattern");
1420	        return;
1421	    }
1422	
1423	    let m = p.marker();
1424	    let text = p.current_text();
1425	
1426	    // We parse an atomic expression even though we only want an identifier for
1427	    // better error recovery. We can mark the whole expression as unexpected
1428	    // instead of going through its pieces one by one.
1429	    code_expr_prec(p, true, 0);
1430	
1431	    if !reassignment {
1432	        let node = &mut p[m];
1433	        if node.kind() == SyntaxKind::Ident {
1434	            if !seen.insert(text) {
1435	                node.convert_to_error(eco_format!(
1436	                    "duplicate {}: {text}",
1437	                    dupe.unwrap_or("binding"),
1438	                ));
1439	            }
1440	        } else {
1441	            node.expected("pattern");
1442	        }
1443	    }
1444	}
1445	
1446	/// Manages parsing a stream of tokens into a tree of [`SyntaxNode`]s.
1447	///
1448	/// The implementation presents an interface that investigates a current `token`
1449	/// with a [`SyntaxKind`] and can take one of the following actions:
1450	///
1451	/// 1. Eat a token: push `token` onto the `nodes` vector as a [leaf
1452	///    node](`SyntaxNode::leaf`) and prepare a new `token` by calling into the
1453	///    lexer.
1454	/// 2. Wrap nodes from a marker to the end of `nodes` (excluding `token` and any
1455	///    attached trivia) into an [inner node](`SyntaxNode::inner`) of a specific
1456	///    `SyntaxKind`.
1457	/// 3. Produce or convert nodes into an [error node](`SyntaxNode::error`) when
1458	///    something expected is missing or something unexpected is found.
1459	///
1460	/// Overall the parser produces a nested tree of `SyntaxNode`s as a "Concrete
1461	/// Syntax Tree." The raw Concrete Syntax Tree should contain the entire source
1462	/// text, and is used as-is for e.g. syntax highlighting and IDE features. In
1463	/// `ast.rs` the CST is interpreted as a lazy view over an "Abstract Syntax
1464	/// Tree." The AST module skips over irrelevant tokens -- whitespace, comments,
1465	/// code parens, commas in function args, etc. -- as it iterates through the
1466	/// tree.
1467	///
1468	/// ### Modes
1469	///
1470	/// The parser manages the transitions between the three modes of Typst through
1471	/// [syntax modes](`SyntaxMode`) and [newline modes](`AtNewline`).
1472	///
1473	/// The syntax modes map to the three Typst modes and are stored in the lexer,
1474	/// changing which `SyntaxKind`s it will generate.
1475	///
1476	/// The newline mode is used to determine whether a newline should end the
1477	/// current expression. If so, the parser temporarily changes `token`'s kind to
1478	/// a fake [`SyntaxKind::End`]. When the parser exits the mode the original
1479	/// `SyntaxKind` is restored.
1480	struct Parser<'s> {
1481	    /// The source text shared with the lexer.
1482	    text: &'s str,
1483	    /// A lexer over the source text with multiple modes. Defines the boundaries
1484	    /// of tokens and determines their [`SyntaxKind`]. Contains the [`SyntaxMode`]
1485	    /// defining our current Typst mode.
1486	    lexer: Lexer<'s>,
1487	    /// The newline mode: whether to insert a temporary end at newlines.
1488	    nl_mode: AtNewline,
1489	    /// The current token under inspection, not yet present in `nodes`. This
1490	    /// acts like a single item of lookahead for the parser.
1491	    ///
1492	    /// When wrapping, this is _not_ included in the wrapped nodes.
1493	    token: Token,
1494	    /// Whether the parser has the expected set of open/close delimiters. This
1495	    /// only ever transitions from `true` to `false`.
1496	    balanced: bool,
1497	    /// Nodes representing the concrete syntax tree of previously parsed text.
1498	    /// In Code and Math, includes previously parsed trivia, but not `token`.
1499	    nodes: Vec<SyntaxNode>,
1500	    /// Parser checkpoints for a given text index. Used for efficient parser
1501	    /// backtracking similar to packrat parsing. See comments above in
1502	    /// [`expr_with_paren`].
1503	    memo: MemoArena,
1504	    /// The current expression nesting depth.
1505	    depth: u32,
1506	}
1507	
1508	/// A single token returned from the lexer with a cached [`SyntaxKind`] and a
1509	/// record of preceding trivia.
1510	#[derive(Debug, Clone)]
1511	struct Token {
1512	    /// The [`SyntaxKind`] of the current token.
1513	    kind: SyntaxKind,
1514	    /// The [`SyntaxNode`] of the current token, ready to be eaten and pushed
1515	    /// onto the end of `nodes`.
1516	    node: SyntaxNode,
1517	    /// The number of preceding trivia before this token.
1518	    n_trivia: usize,
1519	    /// Whether this token's preceding trivia contained a newline.
1520	    newline: Option<Newline>,
1521	    /// The index into `text` of the start of our current token (the end is
1522	    /// stored as the lexer's cursor).
1523	    start: usize,
1524	    /// The index into `text` of the end of the previous token.
1525	    prev_end: usize,
1526	}
1527	
1528	/// Information about newlines in a group of trivia.
1529	#[derive(Debug, Copy, Clone)]
1530	struct Newline {
1531	    /// The column of the start of the next token in its line.
1532	    column: Option<usize>,
1533	    /// Whether any of our newlines were paragraph breaks.
1534	    parbreak: bool,
1535	}
1536	
1537	/// How to proceed with parsing when at a newline.
1538	#[derive(Debug, Copy, Clone, Eq, PartialEq)]
1539	enum AtNewline {
1540	    /// Continue at newlines.
1541	    Continue,
1542	    /// Stop at any newline.
1543	    Stop,
1544	    /// Continue only if there is a continuation with `else` or `.` (Code only).
1545	    ContextualContinue,
1546	    /// Stop only at a parbreak, not normal newlines (Markup only).
1547	    StopParBreak,
1548	    /// Require that the token's column be greater or equal to a column (Markup
1549	    /// only). If this is `0`, acts like `Continue`; if this is `usize::MAX`,
1550	    /// acts like `Stop`.
1551	    RequireColumn(usize),
1552	}
1553	
1554	impl AtNewline {
1555	    /// Whether to stop at a newline or continue based on the current context.
1556	    fn stop_at(self, Newline { column, parbreak }: Newline, kind: SyntaxKind) -> bool {
1557	        match self {
1558	            AtNewline::Continue => false,
1559	            AtNewline::Stop => true,
1560	            #[expect(clippy::match_like_matches_macro)]
1561	            AtNewline::ContextualContinue => match kind {
1562	                SyntaxKind::Else | SyntaxKind::Dot => false,
1563	                _ => true,
1564	            },
1565	            AtNewline::StopParBreak => parbreak,
1566	            AtNewline::RequireColumn(min_col) => {
1567	                // When the column is `None`, the newline doesn't start a
1568	                // column, and we continue parsing. This may happen on the
1569	                // boundary of syntax modes, since we only report a column in
1570	                // Markup.
1571	                column.is_some_and(|column| column <= min_col)
1572	            }
1573	        }
1574	    }
1575	}
1576	
1577	/// A marker representing a node's position in the parser. Mainly used for
1578	/// wrapping, but can also index into the parser to access the node, like
1579	/// `p[m]`.
1580	#[derive(Debug, Copy, Clone, Eq, PartialEq)]
1581	struct Marker(usize);
1582	
1583	// Index into the parser with markers.
1584	impl Index<Marker> for Parser<'_> {
1585	    type Output = SyntaxNode;
1586	
1587	    fn index(&self, m: Marker) -> &Self::Output {
1588	        &self.nodes[m.0]
1589	    }
1590	}
1591	
1592	impl IndexMut<Marker> for Parser<'_> {
1593	    fn index_mut(&mut self, m: Marker) -> &mut Self::Output {
1594	        &mut self.nodes[m.0]
1595	    }
1596	}
