1598	/// Creating/Consuming the parser and getting info about the current token.
1599	impl<'s> Parser<'s> {
1600	    /// Create a new parser starting from the given text offset and syntax mode.
1601	    fn new(text: &'s str, offset: usize, mode: SyntaxMode) -> Self {
1602	        let mut lexer = Lexer::new(text, mode);
1603	        lexer.jump(offset);
1604	        let nl_mode = AtNewline::Continue;
1605	        let mut nodes = vec![];
1606	        let token = Self::lex(&mut nodes, &mut lexer, nl_mode);
1607	        Self {
1608	            text,
1609	            lexer,
1610	            nl_mode,
1611	            token,
1612	            balanced: true,
1613	            nodes,
1614	            memo: MemoArena::default(),
1615	            depth: 0,
1616	        }
1617	    }
1618	
1619	    /// Consume the parser, yielding the full vector of parsed [`SyntaxNode`]s.
1620	    fn finish(self) -> Vec<SyntaxNode> {
1621	        self.nodes
1622	    }
1623	
1624	    /// Consume the parser, generating a single top-level node.
1625	    fn finish_into(self, kind: SyntaxKind) -> SyntaxNode {
1626	        assert!(self.at(SyntaxKind::End));
1627	        SyntaxNode::inner(kind, self.finish())
1628	    }
1629	
1630	    /// Similar to a `peek()` function: returns the `kind` of the next token to
1631	    /// be eaten.
1632	    fn current(&self) -> SyntaxKind {
1633	        self.token.kind
1634	    }
1635	
1636	    /// Whether the current token is a given [`SyntaxKind`].
1637	    fn at(&self, kind: SyntaxKind) -> bool {
1638	        self.token.kind == kind
1639	    }
1640	
1641	    /// Whether the current token is contained in a [`SyntaxSet`].
1642	    fn at_set(&self, set: SyntaxSet) -> bool {
1643	        set.contains(self.token.kind)
1644	    }
1645	
1646	    /// Whether we're at the end of the token stream.
1647	    ///
1648	    /// Note: This might be a fake end due to the newline mode.
1649	    fn end(&self) -> bool {
1650	        self.at(SyntaxKind::End)
1651	    }
1652	
1653	    /// If we're at the given `kind` with no preceding trivia tokens.
1654	    fn directly_at(&self, kind: SyntaxKind) -> bool {
1655	        self.token.kind == kind && !self.had_trivia()
1656	    }
1657	
1658	    /// Whether `token` had any preceding trivia.
1659	    fn had_trivia(&self) -> bool {
1660	        self.token.n_trivia > 0
1661	    }
1662	
1663	    /// Whether `token` had a newline among any of its preceding trivia.
1664	    fn had_newline(&self) -> bool {
1665	        self.token.newline.is_some()
1666	    }
1667	
1668	    /// The number of characters until the most recent newline from the start of
1669	    /// the current token. Uses a cached value from the newline mode if present.
1670	    fn current_column(&self) -> usize {
1671	        self.token
1672	            .newline
1673	            .and_then(|newline| newline.column)
1674	            .unwrap_or_else(|| self.lexer.column(self.token.start))
1675	    }
1676	
1677	    /// The current token's text.
1678	    fn current_text(&self) -> &'s str {
1679	        &self.text[self.token.start..self.current_end()]
1680	    }
1681	
1682	    /// The offset into `text` of the current token's start.
1683	    fn current_start(&self) -> usize {
1684	        self.token.start
1685	    }
1686	
1687	    /// The offset into `text` of the current token's end.
1688	    fn current_end(&self) -> usize {
1689	        self.lexer.cursor()
1690	    }
1691	
1692	    /// The offset into `text` of the previous token's end.
1693	    fn prev_end(&self) -> usize {
1694	        self.token.prev_end
1695	    }
1696	}
