1698	// The main parsing interface for generating tokens and eating/modifying nodes.
1699	impl<'s> Parser<'s> {
1700	    /// A marker that will point to the current token in the parser once it's
1701	    /// been eaten.
1702	    fn marker(&self) -> Marker {
1703	        Marker(self.nodes.len())
1704	    }
1705	
1706	    /// A marker that will point to first trivia before this token in the
1707	    /// parser (or the token itself if no trivia precede it).
1708	    fn before_trivia(&self) -> Marker {
1709	        Marker(self.nodes.len() - self.token.n_trivia)
1710	    }
1711	
1712	    /// Eat the current node and return a reference for in-place mutation.
1713	    #[track_caller]
1714	    fn eat_and_get(&mut self) -> &mut SyntaxNode {
1715	        let offset = self.nodes.len();
1716	        self.eat();
1717	        &mut self.nodes[offset]
1718	    }
1719	
1720	    /// Eat the token if at `kind`. Returns `true` if eaten.
1721	    ///
1722	    /// Note: In Math and Code, this will ignore trivia in front of the
1723	    /// `kind`, To forbid skipping trivia, consider using `eat_if_direct`.
1724	    fn eat_if(&mut self, kind: SyntaxKind) -> bool {
1725	        let at = self.at(kind);
1726	        if at {
1727	            self.eat();
1728	        }
1729	        at
1730	    }
1731	
1732	    /// Assert that we are at the given [`SyntaxKind`] and eat it. This should
1733	    /// be used when moving between functions that expect to start with a
1734	    /// specific token.
1735	    #[track_caller]
1736	    fn assert(&mut self, kind: SyntaxKind) {
1737	        assert_eq!(self.token.kind, kind);
1738	        self.eat();
1739	    }
1740	
1741	    /// Convert the current token's [`SyntaxKind`] and eat it.
1742	    fn convert_and_eat(&mut self, kind: SyntaxKind) {
1743	        // Only need to replace the node here.
1744	        self.token.node.convert_to_kind(kind);
1745	        self.eat();
1746	    }
1747	
1748	    /// Eat the current token by saving it to the `nodes` vector, then move
1749	    /// the lexer forward to prepare a new token.
1750	    fn eat(&mut self) {
1751	        self.nodes.push(std::mem::take(&mut self.token.node));
1752	        self.token = Self::lex(&mut self.nodes, &mut self.lexer, self.nl_mode);
1753	    }
1754	
1755	    /// Detach the parsed trivia nodes from this token (but not newline info) so
1756	    /// that subsequent wrapping will include the trivia.
1757	    fn flush_trivia(&mut self) {
1758	        self.token.n_trivia = 0;
1759	        self.token.prev_end = self.token.start;
1760	    }
1761	
1762	    /// Wrap the nodes from a marker up to (but excluding) the current token in
1763	    /// a new [inner node](`SyntaxNode::inner`) of the given kind. This is an
1764	    /// easy interface for creating nested syntax nodes _after_ having parsed
1765	    /// their children.
1766	    fn wrap(&mut self, from: Marker, kind: SyntaxKind) {
1767	        let to = self.before_trivia().0;
1768	        let from = from.0.min(to);
1769	        let children = self.nodes.drain(from..to).collect();
1770	        self.nodes.insert(from, SyntaxNode::inner(kind, children));
1771	    }
1772	
1773	    /// Wrap the nodes from a marker up to (but excluding) the current token in
1774	    /// a new [error node](`SyntaxNode::error`) with the given message. This is
1775	    /// an easy interface for creating a syntax error _after_ having parsed its
1776	    /// children.
1777	    fn wrap_error(&mut self, from: Marker, message: impl Into<EcoString>) {
1778	        let to = self.before_trivia().0;
1779	        let from = from.0.min(to);
1780	        let len: usize = self.nodes.drain(from..to).map(|node| node.len()).sum();
1781	        let end = self.token.prev_end;
1782	        let start = end - len;
1783	        let text = &self.text[start..end];
1784	        self.nodes.insert(from, SyntaxNode::error(message.into(), text));
1785	    }
1786	
1787	    /// Parse within the [`SyntaxMode`] for subsequent tokens (does not change the
1788	    /// current token). This may re-lex the final token on exit.
1789	    ///
1790	    /// This function effectively repurposes the call stack as a stack of modes.
1791	    fn enter_modes(
1792	        &mut self,
1793	        mode: SyntaxMode,
1794	        stop: AtNewline,
1795	        func: impl FnOnce(&mut Parser<'s>),
1796	    ) {
1797	        let previous = self.lexer.mode();
1798	        self.lexer.set_mode(mode);
1799	        self.with_nl_mode(stop, func);
1800	        if mode != previous {
1801	            self.lexer.set_mode(previous);
1802	            self.lexer.jump(self.token.prev_end);
1803	            self.nodes.truncate(self.nodes.len() - self.token.n_trivia);
1804	            self.token = Self::lex(&mut self.nodes, &mut self.lexer, self.nl_mode);
1805	        }
1806	    }
1807	
1808	    /// Parse within the [`AtNewline`] mode for subsequent tokens (does not
1809	    /// change the current token). This may re-lex the final token on exit.
1810	    ///
1811	    /// This function effectively repurposes the call stack as a stack of modes.
1812	    fn with_nl_mode(&mut self, mode: AtNewline, func: impl FnOnce(&mut Parser<'s>)) {
1813	        let previous = self.nl_mode;
1814	        self.nl_mode = mode;
1815	        func(self);
1816	        self.nl_mode = previous;
1817	        if let Some(newline) = self.token.newline
1818	            && mode != previous
1819	        {
1820	            // Restore our actual token's kind or insert a fake end.
1821	            let actual_kind = self.token.node.kind();
1822	            if self.nl_mode.stop_at(newline, actual_kind) {
1823	                self.token.kind = SyntaxKind::End;
1824	            } else {
1825	                self.token.kind = actual_kind;
1826	            }
1827	        }
1828	    }
1829	
1830	    /// Move the lexer forward and prepare the current token. In Code, this
1831	    /// might insert a temporary [`SyntaxKind::End`] based on our newline mode.
1832	    ///
1833	    /// This is not a method on `self` because we need a valid token before we
1834	    /// can initialize the parser.
1835	    fn lex(nodes: &mut Vec<SyntaxNode>, lexer: &mut Lexer, nl_mode: AtNewline) -> Token {
1836	        let prev_end = lexer.cursor();
1837	        let mut start = prev_end;
1838	        let (mut kind, mut node) = lexer.next();
1839	        let mut n_trivia = 0;
1840	        let mut space_with_newline = false;
1841	        let mut parbreak = false;
1842	
1843	        while kind.is_trivia() {
1844	            space_with_newline |= kind == SyntaxKind::SpaceWithNewline;
1845	            parbreak |= kind == SyntaxKind::Parbreak;
1846	            n_trivia += 1;
1847	            nodes.push(node);
1848	            start = lexer.cursor();
1849	            (kind, node) = lexer.next();
1850	        }
1851	
1852	        let newline = if space_with_newline || parbreak {
1853	            let column =
1854	                (lexer.mode() == SyntaxMode::Markup).then(|| lexer.column(start));
1855	            let newline = Newline { column, parbreak };
1856	            if nl_mode.stop_at(newline, kind) {
1857	                // Insert a temporary `SyntaxKind::End` to halt the parser.
1858	                // The actual kind will be restored from `node` later.
1859	                kind = SyntaxKind::End;
1860	            }
1861	            Some(newline)
1862	        } else {
1863	            None
1864	        };
1865	
1866	        Token { kind, node, n_trivia, newline, start, prev_end }
1867	    }
1868	}
1869	
1870	/// Extra parser state for efficiently recovering from mispredicted parses.
1871	///
1872	/// This is the same idea as packrat parsing, but we use it only in the limited
1873	/// case of parenthesized structures. See [`expr_with_paren`] for more.
1874	#[derive(Default)]
1875	struct MemoArena {
1876	    /// A single arena of previously parsed nodes (to reduce allocations).
1877	    /// Memoized ranges refer to unique sections of the arena.
1878	    arena: Vec<SyntaxNode>,
1879	    /// A map from the parser's current position to a range of previously parsed
1880	    /// nodes in the arena and a checkpoint of the parser's state. These allow
1881	    /// us to reset the parser to avoid parsing the same location again.
1882	    memo_map: FxHashMap<MemoKey, (Range<usize>, PartialState)>,
1883	}
1884	
1885	/// A type alias for the memo key so it doesn't get confused with other usizes.
1886	///
1887	/// The memo is keyed by the index into `text` of the current token's start.
1888	type MemoKey = usize;
1889	
1890	/// A checkpoint of the parser which can fully restore it to a previous state.
1891	struct Checkpoint {
1892	    node_len: usize,
1893	    state: PartialState,
1894	}
1895	
1896	/// State needed to restore the parser's current token and the lexer (but not
1897	/// the nodes vector).
1898	#[derive(Clone)]
1899	struct PartialState {
1900	    cursor: usize,
1901	    lex_mode: SyntaxMode,
1902	    token: Token,
1903	}
1904	
1905	/// The Memoization interface.
1906	impl Parser<'_> {
1907	    /// Store the already parsed nodes and the parser state into the memo map by
1908	    /// extending the arena and storing the extended range and a checkpoint.
1909	    fn memoize_parsed_nodes(&mut self, key: MemoKey, prev_len: usize) {
1910	        let Checkpoint { state, node_len } = self.checkpoint();
1911	        let memo_start = self.memo.arena.len();
1912	        self.memo.arena.extend_from_slice(&self.nodes[prev_len..node_len]);
1913	        let arena_range = memo_start..self.memo.arena.len();
1914	        self.memo.memo_map.insert(key, (arena_range, state));
1915	    }
1916	
1917	    /// Try to load a memoized result, return `None` if we did or `Some` (with a
1918	    /// checkpoint and a key for the memo map) if we didn't.
1919	    fn restore_memo_or_checkpoint(&mut self) -> Option<(MemoKey, Checkpoint)> {
1920	        // We use the starting index of the current token as our key.
1921	        let key: MemoKey = self.current_start();
1922	        match self.memo.memo_map.get(&key).cloned() {
1923	            Some((range, state)) => {
1924	                self.nodes.extend_from_slice(&self.memo.arena[range]);
1925	                // It's important that we don't truncate the nodes vector since
1926	                // it may have grown or shrunk (due to other memoization or
1927	                // error reporting) since we made this checkpoint.
1928	                self.restore_partial(state);
1929	                None
1930	            }
1931	            None => Some((key, self.checkpoint())),
1932	        }
1933	    }
1934	
1935	    /// Restore the parser to the state at a checkpoint.
1936	    fn restore(&mut self, checkpoint: Checkpoint) {
1937	        self.nodes.truncate(checkpoint.node_len);
1938	        self.restore_partial(checkpoint.state);
1939	    }
1940	
1941	    /// Restore parts of the checkpoint excluding the nodes vector.
1942	    fn restore_partial(&mut self, state: PartialState) {
1943	        self.lexer.jump(state.cursor);
1944	        self.lexer.set_mode(state.lex_mode);
1945	        self.token = state.token;
1946	    }
1947	
1948	    /// Save a checkpoint of the parser state.
1949	    fn checkpoint(&self) -> Checkpoint {
1950	        let node_len = self.nodes.len();
1951	        let state = PartialState {
1952	            cursor: self.lexer.cursor(),
1953	            lex_mode: self.lexer.mode(),
1954	            token: self.token.clone(),
1955	        };
1956	        Checkpoint { node_len, state }
1957	    }
1958	}
1959	
1960	/// Functions for eating expected or unexpected tokens and generating errors if
1961	/// we don't get what we expect.
1962	impl Parser<'_> {
1963	    /// Consume the given `kind` or produce an error.
1964	    fn expect(&mut self, kind: SyntaxKind) -> bool {
1965	        let at = self.at(kind);
1966	        if at {
1967	            self.eat();
1968	        } else if kind == SyntaxKind::Ident && self.token.kind.is_keyword() {
1969	            self.trim_errors();
1970	            self.eat_and_get().expected(kind.name());
1971	        } else {
1972	            self.balanced &= !kind.is_grouping();
1973	            self.expected(kind.name());
1974	        }
1975	        at
1976	    }
1977	
1978	    /// Consume the given closing delimiter or produce an error for the matching
1979	    /// opening delimiter at `open`.
1980	    #[track_caller]
1981	    fn expect_closing_delimiter(&mut self, open: Marker, kind: SyntaxKind) -> bool {
1982	        let at = self.eat_if(kind);
1983	        if !at {
1984	            self.nodes[open.0].convert_to_error("unclosed delimiter");
1985	        }
1986	        at
1987	    }
1988	
1989	    /// Produce an error that the given `thing` was expected. If the parser is
1990	    /// at an erroneous token, this will instead eat that token and continue.
1991	    fn expected(&mut self, thing: &str) {
1992	        if self.token.kind.is_error() {
1993	            // If we encounter an erroneous token when something was expected,
1994	            // we need to actually consume the token. If we don't, and we then
1995	            // proceed to exit our current lexing mode, future incremental
1996	            // reparsing could fail to lex the token in the correct mode.
1997	            //
1998	            // Example: When parsing an unclosed string in `#import "str`,
1999	            // we need to make sure the string is lexed as code, because if
2000	            // it were lexed as markup, a future insert of a closing quote
2001	            // would only be adjacent to markup text, and wouldn't lex as a
2002	            // string when reparsing, causing a difference between the full
2003	            // parse and the incremental parse.
2004	            self.trim_errors();
2005	            self.eat();
2006	        } else if !self.after_error() {
2007	            self.expected_at(self.before_trivia(), thing);
2008	        }
2009	    }
2010	
2011	    /// Whether the last non-trivia node is an error.
2012	    fn after_error(&mut self) -> bool {
2013	        let m = self.before_trivia();
2014	        m.0 > 0 && self.nodes[m.0 - 1].kind().is_error()
2015	    }
2016	
2017	    /// Produce an error that the given `thing` was expected at the position
2018	    /// of the marker `m`.
2019	    fn expected_at(&mut self, m: Marker, thing: &str) {
2020	        let error = SyntaxNode::error(eco_format!("expected {thing}"), "");
2021	        self.nodes.insert(m.0, error);
2022	    }
2023	
2024	    /// Add a hint to a trailing error.
2025	    fn hint(&mut self, hint: &str) {
2026	        let m = self.before_trivia();
2027	        if let Some(error) = self.nodes.get_mut(m.0 - 1) {
2028	            error.hint(hint);
2029	        }
2030	    }
2031	
2032	    /// Consume the next token (if any) and produce an error stating that it was
2033	    /// unexpected.
2034	    fn unexpected(&mut self) {
2035	        self.trim_errors();
2036	        self.balanced &= !self.token.kind.is_grouping();
2037	        self.eat_and_get().unexpected();
2038	    }
2039	
2040	    /// Remove trailing errors with zero length.
2041	    fn trim_errors(&mut self) {
2042	        let Marker(end) = self.before_trivia();
2043	        let mut start = end;
2044	        while start > 0
2045	            && self.nodes[start - 1].kind().is_error()
2046	            && self.nodes[start - 1].is_empty()
2047	        {
2048	            start -= 1;
2049	        }
2050	        self.nodes.drain(start..end);
2051	    }
2052	
2053	    /// Check if the maximum depth has been exceeded. If so, generate an error
2054	    /// and try to make a best effort recovery using the `stop_set` as a guide.
2055	    ///
2056	    /// This function isn't strictly necessary, but it is an optimization to
2057	    /// generate one combined error instead of an error message for every
2058	    /// balanced set of tokens. In the pathological case an error would be
2059	    /// generated by [`Self::increase_depth`] for every single token until
2060	    /// the `stop_set` of the parent function is reached.
2061	    fn check_depth_until(&mut self, stop_set: SyntaxSet) -> Option<&mut Self> {
2062	        if self.depth < MAX_DEPTH {
2063	            Some(self)
2064	        } else {
2065	            self.depth_check_error(Some(stop_set));
2066	            None
2067	        }
2068	    }
2069	
2070	    /// Check if the maximum depth has been exceeded. If so, generate an error
2071	    /// and try to make a best effort recovery. Otherwise increase the depth and
2072	    /// return a handle that automatically decreases it again when dropped.
2073	    fn increase_depth(&mut self) -> Option<impl DerefMut<Target = Self>> {
2074	        if self.depth < MAX_DEPTH {
2075	            self.depth += 1;
2076	            Some(defer(self, |p| p.depth -= 1))
2077	        } else {
2078	            self.depth_check_error(None);
2079	            None
2080	        }
2081	    }
2082	
2083	    /// Generate an error for an exceeded maximum depth check.
2084	    fn depth_check_error(&mut self, stop_set: Option<SyntaxSet>) {
2085	        let m = self.marker();
2086	
2087	        let mut balance: usize = 0;
2088	        // This function has to guarantee some sort of forward progress,
2089	        // otherwise the parser might loop indefinitely. One token is eaten in
2090	        // all cases, if that token is an opening delimiter, try to balance the
2091	        // opening and closing grouping delimiters before continuing.
2092	        self.with_nl_mode(AtNewline::Continue, |p| {
2093	            loop {
2094	                // We don't need to add `MathOpening/MathClosing` since they
2095	                // don't actually contribute to delimiter balance.
2096	                if p.at_set(syntax_set!(LeftBracket, LeftBrace, LeftParen)) {
2097	                    balance = balance.saturating_add(1);
2098	                } else if p.at_set(syntax_set!(RightBracket, RightBrace, RightParen)) {
2099	                    balance = balance.saturating_sub(1);
2100	                }
2101	                p.eat();
2102	
2103	                let at_stop = stop_set.is_none_or(|s| p.at_set(s));
2104	                if (balance == 0 && at_stop) || p.end() {
2105	                    break;
2106	                }
2107	            }
2108	        });
2109	
2110	        self.wrap_error(m, "maximum parsing depth exceeded");
2111	    }
2112	}
